function makePreviewWaves(spec) {
  const labels = spec.labels;
  const requires = spec.requires;
  const count = labels.length;
  const remaining = new Array(count).fill(0);
  const done = new Array(count).fill(false);
  const waves = [];

  for (let i = 0; i < count; i++) {
    for (let j = 0; j < count; j++) {
      if (requires[i][j] === 1) remaining[i]++;
    }
  }

  let completed = 0;

  while (completed < count) {
    const wave = [];

    for (let i = 0; i < count; i++) {
      if (!done[i] && remaining[i] === 0) {
        wave.push(labels[i]);
      }
    }

    if (wave.length === 0) return null;

    for (let i = 0; i < count; i++) {
      if (!done[i] && remaining[i] === 0) {
        done[i] = true;
        completed++;
      }
    }

    for (let i = 0; i < count; i++) {
      if (done[i]) {
        for (let j = 0; j < count; j++) {
          if (!done[j] && requires[j][i] === 1) {
            remaining[j]--;
          }
        }
      }
    }

    waves.push(wave);
  }

  return waves;
}
